{
	list_del(&pool->region_node);
	kfree(pool);
}
```
```
void dmem_cgroup_pool_state_put(struct dmem_cgroup_pool_state *pool)
{
	if (pool)
		css_put(&pool->cs->css);
}
```
```
static struct dmem_cgroup_pool_state *
get_cg_pool_unlocked(...)
{
	pool = find_cg_pool_locked(cg, region);
	if (pool && !READ_ONCE(pool->inited))
		pool = NULL;
	rcu_read_unlock();
	while (!pool) {
		spin_lock(&dmemcg_lock);
		...
		if (!IS_ERR(pool))
			spin_unlock(&dmemcg_lock);
		...
	}
	return pool;
}
```
Reason:
The pool was freed directly via `kfree(pool)` without any reference tracking, and callers (e.g., `dmem_cgroup_pool_state_put`, `get_cg_pool_unlocked`) did not increment or decrement a pool reference count. This allowed the pool to be deallocated (e.g., during region unregistration) while other code paths still held pointers to it, causing use-after-free.

The code statements that fix the bug are:
```
static void dmemcg_pool_put(struct dmem_cgroup_pool_state *pool)
{
	if (!refcount_dec_and_test(&pool->ref))
		return;
	call_rcu(&pool->rcu, dmemcg_pool_free_rcu);
}
```
```
static void free_cg_pool(struct dmem_cgroup_pool_state *pool)
{
	list_del(&pool->region_node);
	dmemcg_pool_put(pool);
}
```
```
void dmem_cgroup_pool_state_put(struct dmem_cgroup_pool_state *pool)
{
	if (pool) {
		css_put(&pool->cs->css);
		dmemcg_pool_put(pool);
	}
}
```
```
static struct dmem_cgroup_pool_state *
get_cg_pool_unlocked(...)
{
	...
	spin_lock(&dmemcg_lock);
	if (!IS_ERR(pool))
		dmemcg_pool_get(pool);
	spin_unlock(&dmemcg_lock);
	return pool;
}
