			if (WARN_ON_ONCE(css == &limit_pool->cs->css))
				break;
		}
		css = next_css;

		found_descendant = false;
		dmemcg_iter = container_of(css, struct dmemcg_state, css);

		list_for_each_entry_rcu(pool, &dmemcg_iter->pools, css_node) {
			if (pool_parent(pool) == parent_pool) {
